/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: parse, withLookup
 * Tests
 *   - a server-shaped review summary parses with the catalog trigger, the exact-count basis, subset comparisons, review paths, precision, flags and pairs
 *   - a missing or malformed value revision, extra keys, forged paths, rows on a member path and a member that is not a slot are refused
 *   - an active run's progress parses within its bounds, numbers and times only, and a view without it parses too
 *   - the identity read parses bound, conflicting and unbound rows, the label, more candidates than an import reads and Credit views
 *   - a decision without its bound ID, a preselection with an extra key, an Album or track candidate and a malformed revision are refused
 *   - the identity read's default selection and kept expected tracklist are required, strict and well formed
 *   - each list is bounded where the server bounds it: 406 answers, 25 candidates, 512 identities and the label's 31,273 candidates, 100 members, 71 new Album and 70 new member Credits
 * @end-catalog */

import { slotId, slotTwo } from './catalogReviewFixtures.testSupport';
import { guestHandle, leadHandle, reviewIdentityResponse, reviewItunesLookupResponse, reviewLookupResponse, reviewRows, reviewTieLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import { reviewIdentitySchema, reviewLookupResponseSchema } from './catalogReviewLookupApi';

/** The strict review lookup summary and identity read, shaped as the server's allowlists return them. All data is synthetic. */
const parse = (value: unknown) => reviewLookupResponseSchema.safeParse(value);
const withLookup = (edit: (lookup: Record<string, any>) => void) => { const value = reviewLookupResponse() as Record<string, any>; edit(value.lookup); return value; };

test('a server-shaped review summary parses with the catalog trigger, the exact-count basis, subset comparisons, review paths, precision, flags and pairs', () => {
  for (const value of [reviewLookupResponse(), reviewItunesLookupResponse(), reviewTieLookupResponse()]) expect(parse(value).success).toBe(true);
  expect(parse({ ...reviewLookupResponse(), lookup: null }).success).toBe(true);
  const parsed = reviewLookupResponseSchema.parse(reviewLookupResponse()).lookup!;
  expect([parsed.input.trigger, parsed.candidates[0].comparison && 'subset' in parsed.candidates[0].comparison && parsed.candidates[0].comparison.subset?.missingTrackCount,
    parsed.applied!.conflicts[1].precision, parsed.applied!.pairs]).toEqual(['catalog', 1, true, [{ slotId, discNumber: 1, trackNumber: 1 }, { slotId: slotTwo, discNumber: 1, trackNumber: 3 }]]);
  const exact = withLookup(lookup => { lookup.preselection.basis = 'exactTrackCount'; lookup.applied.basis = 'exactTrackCount'; });
  expect(parse(exact).success).toBe(true);
  const differences = withLookup(lookup => { lookup.candidates[0].status = 'notMatching'; lookup.candidates[0].comparison.differences = ['trackCount', 'discCount', 'duration', 'pairing', 'tooManyTracks', 'tracklistInvalid']; });
  expect(parse(differences).success).toBe(true);
  const rows = withLookup(lookup => { lookup.applied.conflicts.push({ path: 'album.expectedTracklist', slotId: null, lookup: reviewRows(), answer: null, musicBrainzId: false, precision: false });
    lookup.applied.flagged.push({ path: `tracks.${slotId}.artists`, reason: 'noTrackCredit' }); lookup.applied.pairs = null; });
  expect(parse(rows).success).toBe(true);
  // A server that sends no subset comparison for a candidate, or no pairing at all, still parses.
  expect(parse(withLookup(lookup => { lookup.candidates[0].comparison.subset = null; lookup.candidates[0].comparison = null; })).success).toBe(true);
  // 406 value paths and answers: the five Album paths and four per member plus one.
  const many = Array.from({ length: 406 }, () => ({ path: 'album.title', slotId: null }));
  expect(parse(withLookup(lookup => { lookup.applied.values = many; lookup.needsAnswer.conflicts = many.map(item => item.path); })).success).toBe(true);
  expect(parse(withLookup(lookup => { lookup.applied.values = [...many, many[0]]; })).success).toBe(false);
  expect(parse(withLookup(lookup => { lookup.needsAnswer.conflicts = Array(407).fill('album.title'); })).success).toBe(false);
});

test('a missing or malformed value revision, extra keys, forged paths, rows on a member path and a member that is not a slot are refused', () => {
  const refused = (edit: (lookup: Record<string, any>) => void) => expect(parse(withLookup(edit)).success).toBe(false);
  expect(parse({ ...reviewLookupResponse(), valueRevision: 3 }).success).toBe(true);
  const { valueRevision: _value, ...withoutValueRevision } = reviewLookupResponse();
  for (const value of [withoutValueRevision, { ...reviewLookupResponse(), valueRevision: -1 }, { ...reviewLookupResponse(), valueRevision: 1.5 }, { ...reviewLookupResponse(), records: [] }])
    expect(parse(value).success).toBe(false);
  expect(parse({ ...reviewLookupResponse(), summary: { ...reviewLookupResponse().summary, identityAnswers: 0 } }).success).toBe(false);
  refused(lookup => { lookup.fence = 1; });
  refused(lookup => { lookup.applied.values.push({ path: 'album.visibility', slotId: null }); });
  refused(lookup => { lookup.applied.values.push({ path: 'tracks.not-a-slot.artists', slotId: null }); });
  refused(lookup => { lookup.needsAnswer.conflicts.push('tracks.__proto__.artists'); });
  refused(lookup => { lookup.applied.conflicts[2].lookup = reviewRows(); });
  refused(lookup => { lookup.applied.conflicts[0] = { ...lookup.applied.conflicts[0], path: 'album.expectedTracklist' }; });
  refused(lookup => { delete lookup.applied.conflicts[0].precision; });
  refused(lookup => { lookup.applied.flagged.push({ path: 'album.label', reason: 'unknownReason' }); });
  refused(lookup => { lookup.candidates[0].comparison.subset.unpairableSlotIds = ['../album']; });
  refused(lookup => { lookup.candidates[0].comparison.subset.pairs[0].trackNumber = 0; });
  refused(lookup => { lookup.candidates[0].comparison.subset.recordingId = 'synthetic'; });
  refused(lookup => { delete lookup.applied.pairs; });
  refused(lookup => { lookup.input.trigger = 'filename'; });
});

test('an active run\'s progress parses within its bounds, numbers and times only, and a view without it parses too', () => {
  const progress = { phase: 'details', done: 3, total: 5, startedAt: '2026-10-25T00:00:00.000Z', updatedAt: '2026-10-25T00:00:14.000Z' };
  const active = (value: unknown) => withLookup(lookup => { lookup.state = 'running'; lookup.progress = value; });
  expect(reviewLookupResponseSchema.parse(active(progress)).lookup!.progress).toEqual(progress);
  expect(reviewLookupResponseSchema.parse(reviewLookupResponse()).lookup!.progress).toBeUndefined();
  for (const phase of ['search', 'details', 'itunes', 'bridge', 'aliases']) expect(parse(active({ ...progress, phase })).success, phase).toBe(true);
  expect(parse(active({ ...progress, done: 100, total: 100 })).success).toBe(true);
  expect(parse(active({ ...progress, done: 0, total: 0 })).success).toBe(true);
  for (const value of [{ ...progress, query: 'Synthetic Album' }, { ...progress, done: 6 }, { ...progress, done: 101, total: 101 }, { ...progress, total: 101 }, { ...progress, phase: 'done' },
    { ...progress, phase: 'other' }, { ...progress, done: -1 }, { ...progress, done: 1.5 }, { ...progress, startedAt: '2026-10-25' }, { ...progress, updatedAt: 'yesterday' },
    { ...progress, startedAt: undefined }, null, 'details']) expect(parse(active(value)).success, JSON.stringify(value)).toBe(false);
});

test('the identity read parses bound, conflicting and unbound rows, the label, more candidates than an import reads and Credit views', () => {
  const data = reviewIdentityResponse();
  expect(reviewIdentitySchema.safeParse(data).success).toBe(true);
  const bound = data.identities[1].bound[0];
  const credit = { creditId: 'credit-0001', subjectType: 'artist', subjectId: bound.id, identity: leadHandle, name: 'Synthetic catalog Artist', role: 'primary', joinPhrase: ' feat. ' };
  const full = { ...data,
    identities: [...data.identities, { ...data.identities[1], id: '70000000-0000-4000-8000-000000000009', state: 'conflicting', bound: [bound, { ...bound, id: 'f'.repeat(24) }] }],
    label: { name: 'Synthetic Label', musicBrainzId: null, state: 'bound', bound: { ...bound, id: 'a'.repeat(24) }, decision: null, preselection: null, needsAnswer: false,
      musicBrainzIdWrite: { scope: 'label', identity: null, musicBrainzId: '00000000-0000-4000-8000-0000000000b1', replaces: null } },
    candidates: { items: Array.from({ length: 2600 }, (_, index) => ({ ...data.candidates.items[0], id: index.toString(16).padStart(24, '0') })), unavailable: [{ kind: 'organization', label: 'Synthetic Label' }] },
    preselections: [{ scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct', candidateId: null, candidateRevision: null }],
    album: { current: [credit], next: [{ ...credit, creditId: null }, { ...credit, creditId: null, subjectId: null, identity: guestHandle, name: 'Synthetic guest', role: 'featured', joinPhrase: null }],
      credits: true, replacedPrimaryArtistIds: [], membersNamingReplaced: [] },
    members: [{ slotId: slotTwo, current: [], next: [{ ...credit, creditId: null, subjectId: null, identity: guestHandle, name: 'Synthetic guest', joinPhrase: null }], removedCreditIds: [], credits: true,
      attribution: { from: 'unknown', to: 'documented' } }] };
  expect(reviewIdentitySchema.safeParse(full).success).toBe(true);
});

test('a decision without its bound ID, a preselection with an extra key, an Album or track candidate and a malformed revision are refused', () => {
  const data = reviewIdentityResponse(), refused = (value: unknown) => expect(reviewIdentitySchema.safeParse(value).success).toBe(false);
  const decision = { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct', candidateId: null, candidateRevision: null };
  expect(reviewIdentitySchema.safeParse({ ...data, identities: [{ ...data.identities[0], decision: { ...decision, boundMusicBrainzId: null } }, data.identities[1]] }).success).toBe(true);
  refused({ ...data, identities: [{ ...data.identities[0], decision }, data.identities[1]] });
  refused({ ...data, preselections: [{ ...decision, boundMusicBrainzId: null }] });
  for (const kind of ['album', 'track']) refused({ ...data, candidates: { ...data.candidates, items: [{ ...data.candidates.items[0], kind }] } });
  refused({ ...data, identities: [data.identities[0], { ...data.identities[1], bound: [{ ...data.identities[1].bound[0], revision: 'cr_synthetic' }] }] });
  refused({ ...data, identities: [{ ...data.identities[0], entries: [{ ...data.identities[0].entries[0], path: 'album.label' }] }] });
  refused({ ...data, musicBrainzIds: [{ scope: 'artist', identity: leadHandle, musicBrainzId: 'not-an-id', replaces: null }] });
  refused({ ...data, members: [{ slotId, current: [], next: [], removedCreditIds: [], credits: false, attribution: null, mediaUrl: '/private' }] });
  refused({ ...data, extra: true });
});

test('the identity read\'s default selection and kept expected tracklist are required, strict and well formed', () => {
  const data = reviewIdentityResponse(), parsed = (value: unknown) => reviewIdentitySchema.safeParse(value).success;
  const rows = [{ discNumber: 1, trackNumber: 1, title: 'Synthetic first track', durationMs: 185_000 }];
  expect([parsed(data), parsed({ ...data, selection: { lists: [], label: true }, keptTracklist: rows })]).toEqual([true, true]);
  const { selection: _selection, ...withoutSelection } = data, { keptTracklist: _kept, ...withoutKept } = data;
  for (const value of [withoutSelection, withoutKept, { ...data, selection: { ...data.selection, extra: true } }, { ...data, selection: { lists: ['album.label'], label: false } },
    { ...data, selection: { lists: ['tracks.not-a-slot.artists'], label: false } }, { ...data, selection: { lists: [], label: 'yes' } },
    { ...data, selection: { lists: Array.from({ length: 102 }, () => 'album.artists'), label: false } }, { ...data, keptTracklist: [] },
    { ...data, keptTracklist: [{ ...rows[0], extra: true }] }, { ...data, keptTracklist: Array.from({ length: 101 }, (_, index) => ({ ...rows[0], trackNumber: index + 1 })) }]) {
    expect(parsed(value), JSON.stringify(value).slice(0, 120)).toBe(false);
  }
});

test('each list is bounded where the server bounds it: 406 answers, 25 candidates, 512 identities and the label\'s 31,273 candidates, 100 members, 71 new Album and 70 new member Credits', () => {
  const at = <T>(item: T, length: number) => Array.from({ length }, () => item);
  const lookupWith = (edit: (lookup: Record<string, any>) => void) => parse(withLookup(edit)).success;
  const conflict = reviewLookupResponse().lookup!.applied!.conflicts[0], flag = { path: 'album.label', reason: 'notApplicable' };
  expect([lookupWith(lookup => { lookup.applied.conflicts = at(conflict, 406); lookup.applied.flagged = at(flag, 406); }),
    lookupWith(lookup => { lookup.applied.conflicts = at(conflict, 407); }), lookupWith(lookup => { lookup.applied.flagged = at(flag, 407); })]).toEqual([true, false, false]);
  const candidate = reviewLookupResponse().lookup!.candidates[0];
  expect([lookupWith(lookup => { lookup.candidates = at(candidate, 25); }), lookupWith(lookup => { lookup.candidates = at(candidate, 26); })]).toEqual([true, false]);
  const pair = { slotId, discNumber: 1, trackNumber: 1 };
  expect([lookupWith(lookup => { lookup.applied.pairs = at(pair, 100); }), lookupWith(lookup => { lookup.applied.pairs = at(pair, 101); }),
    lookupWith(lookup => { lookup.candidates[0].comparison.subset.pairs = at(pair, 101); })]).toEqual([true, false, false]);
  const data = reviewIdentityResponse(), identity = (value: unknown) => reviewIdentitySchema.safeParse(value).success, item = data.candidates.items[0];
  expect([identity({ ...data, candidates: { ...data.candidates, items: at(item, 31_273) } }), identity({ ...data, candidates: { ...data.candidates, items: at(item, 31_274) } })]).toEqual([true, false]);
  expect([identity({ ...data, identities: at(data.identities[0], 512) }), identity({ ...data, identities: at(data.identities[0], 513) })]).toEqual([true, false]);
  const row = data.identities[0];
  expect([identity({ ...data, identities: [{ ...row, entries: at(row.entries[0], 2020), names: at('Synthetic alias', 2020) }] }),
    identity({ ...data, identities: [{ ...row, entries: at(row.entries[0], 2021) }] }), identity({ ...data, identities: [{ ...row, names: at('Synthetic alias', 2021) }] })]).toEqual([true, false, false]);
  const member = { slotId, current: [], next: [], removedCreditIds: [], credits: false, attribution: null };
  expect([identity({ ...data, members: at(member, 100) }), identity({ ...data, members: at(member, 101) })]).toEqual([true, false]);
  // New Credits: the Album's 50 stored, 20 new entries ahead of them and a new label Credit (71); a member's without a label (70).
  const credit = { creditId: null, subjectType: 'artist', subjectId: null, identity: guestHandle, name: 'Synthetic guest', role: 'primary', joinPhrase: null };
  const album = (next: number) => ({ current: at(credit, 50), next: at(credit, next), credits: true, replacedPrimaryArtistIds: [], membersNamingReplaced: [] });
  expect([identity({ ...data, album: album(71) }), identity({ ...data, album: album(72) })]).toEqual([true, false]);
  expect([identity({ ...data, members: [{ ...member, next: at(credit, 70) }] }), identity({ ...data, members: [{ ...member, next: at(credit, 71) }] })]).toEqual([true, false]);
  const preselection = { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct', candidateId: null, candidateRevision: null };
  expect([identity({ ...data, preselections: at(preselection, 513) }), identity({ ...data, preselections: at(preselection, 514) })]).toEqual([true, false]);
});
